import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  carouselButtonClasses,
  carouselClasses,
  carouselContentClasses,
  carouselItemClasses,
  carouselNextClasses,
  carouselPreviousClasses,
  carouselStatusClasses,
  carouselVerticalContentClasses,
  carouselViewportClasses,
} from "./view";
import type { CarouselOrientation } from "./view";

export type { CarouselOrientation };
export {
  carouselButtonClasses,
  carouselCardClasses,
  carouselClasses,
  carouselContentClasses,
  carouselItemClasses,
  carouselNextClasses,
  carouselPreviousClasses,
  carouselStatusClasses,
  carouselVerticalContentClasses,
  carouselViewportClasses,
} from "./view";

export type RootViewConfig = Readonly<{
  children: readonly (Html | string)[];
  className?: string;
  ariaLabel?: string;
}>;

export type ViewportViewConfig = Readonly<{
  children: readonly (Html | string)[];
  className?: string;
}>;

export type ContentViewConfig = Readonly<{
  children: readonly (Html | string)[];
  index: number;
  orientation?: CarouselOrientation;
  className?: string;
}>;

export type ItemViewConfig = Readonly<{
  children: readonly (Html | string)[];
  className?: string;
}>;

export type ButtonViewConfig<ParentMessage> = Readonly<{
  label: string;
  direction: "previous" | "next";
  onClick: ParentMessage;
  className?: string;
}>;

export type StatusViewConfig = Readonly<{
  current: number;
  count: number;
  className?: string;
}>;

const cn = (base: string, className?: string): string =>
  [base, className]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

export const nextIndex = (index: number, count: number): number => {
  if (count <= 0) {
    return 0;
  }

  return (index + 1) % count;
};

export const previousIndex = (index: number, count: number): number => {
  if (count <= 0) {
    return 0;
  }

  return (index - 1 + count) % count;
};

export const rootView = <ParentMessage>({
  children,
  className,
  ariaLabel = "Carousel",
}: RootViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Attribute("role", "region"),
      h.AriaLabel(ariaLabel),
      h.Attribute("aria-roledescription", "carousel"),
      h.DataAttribute("slot", "carousel"),
      h.Class(cn(carouselClasses, className)),
    ],
    children
  );
};

export const viewportView = <ParentMessage>({
  children,
  className,
}: ViewportViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.DataAttribute("slot", "carousel-viewport"),
      h.Class(cn(carouselViewportClasses, className)),
    ],
    children
  );
};

export const contentView = <ParentMessage>({
  children,
  index,
  orientation = "horizontal",
  className,
}: ContentViewConfig): Html => {
  const h = html<ParentMessage>();
  const transform =
    orientation === "vertical"
      ? `translateY(-${index * 100}%)`
      : `translateX(-${index * 100}%)`;
  const base =
    orientation === "vertical"
      ? carouselVerticalContentClasses
      : carouselContentClasses;

  return h.div(
    [
      h.DataAttribute("slot", "carousel-content"),
      h.DataAttribute("orientation", orientation),
      h.Style({ transform }),
      h.Class(cn(base, className)),
    ],
    children
  );
};

export const itemView = <ParentMessage>({
  children,
  className,
}: ItemViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Attribute("role", "group"),
      h.Attribute("aria-roledescription", "slide"),
      h.DataAttribute("slot", "carousel-item"),
      h.Class(cn(carouselItemClasses, className)),
    ],
    children
  );
};

export const buttonView = <ParentMessage>({
  label,
  direction,
  onClick,
  className,
}: ButtonViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();
  const positionClasses =
    direction === "previous"
      ? carouselPreviousClasses
      : carouselNextClasses;

  return h.button(
    [
      h.Type("button"),
      h.AriaLabel(label),
      h.OnClick(onClick),
      h.Class(
        cn(`${carouselButtonClasses} ${positionClasses}`, className)
      ),
    ],
    [direction === "previous" ? "<" : ">"]
  );
};

export const statusView = <ParentMessage>({
  current,
  count,
  className,
}: StatusViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.p(
    [
      h.Attribute("aria-live", "polite"),
      h.Class(cn(carouselStatusClasses, className)),
    ],
    [`Slide ${current} of ${count}`]
  );
};

export type CarouselOrientation = "horizontal" | "vertical";

export const carouselClasses = "relative w-full";

export const carouselViewportClasses = "overflow-hidden rounded-xl";

export const carouselContentClasses =
  "flex transition-transform duration-300 ease-out";

export const carouselVerticalContentClasses =
  "flex flex-col transition-transform duration-300 ease-out";

export const carouselItemClasses = "min-w-0 shrink-0 grow-0 basis-full";

export const carouselCardClasses =
  "flex aspect-square items-center justify-center rounded-xl border border-gray-200 bg-gray-50 text-4xl font-semibold text-gray-400";

export const carouselButtonClasses =
  "inline-flex h-9 w-9 items-center justify-center rounded-full border border-gray-300 bg-white text-sm font-semibold text-gray-700 shadow-sm transition hover:bg-gray-50 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent-600 disabled:pointer-events-none disabled:opacity-50";

export const carouselPreviousClasses =
  "absolute left-2 top-1/2 -translate-y-1/2";

export const carouselNextClasses =
  "absolute right-2 top-1/2 -translate-y-1/2";

export const carouselStatusClasses = "text-sm text-gray-600";

import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { describe, expect, test } from "vitest";

import * as Carousel from "./index";

describe("Carousel registry view", () => {
  test("renders labelled carousel anatomy", () => {
    const view = (): Html => {
      const h = html<never>();

      return Carousel.rootView<never>({
        ariaLabel: "Featured slides",
        children: [
          Carousel.viewportView<never>({
            children: [
              Carousel.contentView<never>({
                index: 0,
                children: [
                  Carousel.itemView<never>({ children: [h.div([], ["1"])] }),
                  Carousel.itemView<never>({ children: [h.div([], ["2"])] }),
                ],
              }),
            ],
          }),
        ],
      });
    };

    Scene.scene(
      {
        update: (model: undefined): readonly [undefined, []] => [model, []],
        view,
      },
      Scene.with(undefined),
      Scene.expect(
        Scene.role("region", { name: "Featured slides" })
      ).toHaveAttr("aria-roledescription", "carousel"),
      Scene.expect(Scene.text("1")).toExist(),
      Scene.expect(Scene.text("2")).toExist()
    );
  });

  test("wraps indices", () => {
    expect(Carousel.nextIndex(4, 5)).toBe(0);
    expect(Carousel.previousIndex(0, 5)).toBe(4);
  });
});
